$error=null;$ctx=[];$runtime=[];$settings=[];$health=[];$latestRelease=null;$metrics=['verified'=>0,'releases'=>0,'migrations'=>0,'offsite'=>0];
try{$pdo=business_db();deployment_step19_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=deployment_step19_context($pdo);$orgId=(int)$ctx['organization_id'];$runtime=deployment_step19_runtime_checks($pdo);$settings=deployment_step19_settings($pdo,$orgId);$health=deployment_step19_health($pdo,false);$s=$pdo->prepare("SELECT COUNT(*) FROM backup_records WHERE organization_id=? AND verification_status='verified' AND status<>'expired'");$s->execute([$orgId]);$metrics['verified']=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM deployment_releases WHERE organization_id=?");$s->execute([$orgId]);$metrics['releases']=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM deployment_migration_runs WHERE organization_id=?");$s->execute([$orgId]);$metrics['migrations']=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM deployment_offsite_targets WHERE organization_id=? AND is_enabled=1 AND last_status='pass'");$s->execute([$orgId]);$metrics['offsite']=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT * FROM deployment_releases WHERE organization_id=? ORDER BY id DESC LIMIT 1");$s->execute([$orgId]);$latestRelease=$s->fetch()?:null;}catch(Throwable $e){$error=$e->getMessage();}
