oot database credentials and a verified recovery point.</p><div class="os-status-row"><span class="os-chip good"><?= deployment_step19_h(strtoupper((string)($runtime['environment']??'LOCAL'))) ?></span><span class="os-chip <?= ($health['status']??'review')==='pass'?'good':'' ?>"><?= deployment_step19_h(strtoupper((string)($health['status']??'review'))) ?> HEALTH</span><span class="os-chip"><?= (int)$metrics['verified'] ?> verified backup(s)</span><span class="os-chip"><?= !empty($settings['maintenance_enabled'])?'MAINTENANCE ON':'MAINTENANCE OFF' ?></span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Deployment diagnostic:</strong> <?= deployment_step19_h($error) ?></div><?php else:?><section class="s10-kpis"><div class="s10-kpi"><small>Environment</small><strong><?= deployment_step19_h(strtoupper($runtime['environment'])) ?></strong><span><?= deployment_step19_h($runtime['app_url']?:'HWC_APP_URL not set') ?></span></div><div class="s10-kpi"><small>HTTPS</small><strong><?= $runtime['is_https']?'YES':'NO' ?></strong><span><?= deployment_step19_env()==='local'?'not required locally':'production transport' ?></span></div><div class="s10-kpi"><small>Verified Recovery</small><strong><?= (int)$metrics['verified'] ?></strong><span>STEP 18 packages</span></div><div class="s10-kpi"><small>Releases</small><strong><?= (int)$metrics['releases'] ?></strong><span><?= $latestRelease?deployment_step19_h($latestRelease['version_label']):'none registered' ?></span></div><div class="s10-kpi"><small>Migration Plans</small><strong><?= (int)$metrics['migrations'] ?></strong><span>local → staging/production</span></div><div class="s10-kpi"><small>Offsite Targets</small><strong><?= (int)$metrics['offsite'] ?></strong><span>verified target(s)</span></div></section><section class="s10-grid"><article class="s10-card s10-span-7"><h2>Production Gates</h2><p>These gates become mandatory only when <code>HWC_APP_ENV=production</code>.</p><div class="s10-checks"><div class="s10-check <?= $runtime['production_url_ready']?'good':'warn' ?>"><div><b>HTTPS App URL</b><span>HWC_APP_URL must be https://...</span></div><strong><?= d19_badge($runtime['production_url_ready']) ?></strong></div><div class="s10-check <?= $runtime['production_db_credentials_ready']?'good':'warn' ?>"><div><b>Dedicated DB credentials</b><span>Production must not use root or an empty password.</span></div><strong><?= d19_badge($runtime['production_db_credentials_ready']) ?></strong></div><div class="s10-check <?= $runtime['allowed_hosts_ready']?'good':'warn' ?>"><div><b>Host allowlist</b><span>HWC_ALLOWED_HOSTS controls accepted production hosts.</span></div><strong><?= d19_badge($runtime['allowed_hosts_ready']) ?></strong></div><div class="s10-check <?= $runtime['health_token_ready']?'good':'warn' ?>"><div><b>Private health token</b><span>Required for external production health probes.</span></div><strong><?= d19_badge($runtime['health_token_ready']) ?></strong></div><div class="s10-check <?= $metrics['verified']>0?'good':'warn' ?>"><div><b>Verified recovery point</b><span>Required before a production release can be marked deployed.</span></div><strong><?= d19_badge($metrics['verified']>0) ?></strong></div></div></article><aside class="s10-card s10-span-5"><h2>Deployment Path</h2><div class="s10-list"><div class="s10-row"><div><b>1. Environment</b><small>Configure secrets outside Git.</small></div><a class="s10-link" href="environment_center.php">Open →</a></div><div class="s10-row"><div><b>2. Recovery Copy</b><small>Create + verify a STEP 18 backup.</small></div><a class="s10-link" href="backup_center.php">Backup →</a></div><div class="s10-row"><div><b>3. Migration Plan</b><small>Use encrypted restore as the data boundary.</small></div><a class="s10-link" href="migration_center.php">Plan →</a></div><div class="s10-row"><div><b>4. Health</b><small>Validate DB, PHP, TLS and access rules.</small></div><a class="s10-link" href="production_health.php">Check →</a></div><div class="s10-row"><div><b>5. Release</b><small>Record the exact deployed version/SHA.</small></div><a class="s10-link" href="deployment_releases.php">Release →</a></div></div></aside></section><?php endif;?></main></div></body></html>